    """Split a total into whole-cent parts proportional to weights.

    Equal splits floor each share (retaining contractual reconciliation behavior);
    weighted splits distribute remainder units by largest remainder so parts sum
    to the total.
    """
    if not weights:
        return []
    denom = sum(weights)
    if denom == 0:
        return [0] * len(weights)

