    total = abs(total_cents)

    if len(set(weights)) <= 1:
        return [sign * (total * w // denom) for w in weights]

    parts = [total * w // denom for w in weights]
    shortfall = total - sum(parts)
    if shortfall > 0:
        remainders = [(total * w) % denom for w in weights]
        ranked_indices = sorted(
            range(len(weights)), key=lambda i: remainders[i], reverse=True
        )
        for i in range(shortfall):
            parts[ranked_indices[i]] += 1

    return [sign * p for p in parts]

