def allocate_largest(total_cents: int, weights: list[int]) -> list[int]:
    denom = sum(weights)
    parts = [total_cents * w // denom for w in weights]
    if len(set(weights)) > 1:
        # largest remainder
        rem = sorted(range(len(weights)), key=lambda i: (total_cents * weights[i] % denom), reverse=True)
        for i in range(total_cents - sum(parts)):
            parts[rem[i]] += 1
    return parts

